:where(html:not(.dark)) :is(.op-sidebar, .op-panel-sidebar) { background: {{sidebar_light_bg}}; --color-page: {{sidebar_light_bg}}; --color-inset: {{sidebar_light_bg}}; --color-panel: color-mix(in oklab, {{sidebar_light_text}} 9%, {{sidebar_light_bg}}); --color-raised: color-mix(in oklab, {{sidebar_light_text}} 20%, {{sidebar_light_bg}}); --color-muted: color-mix(in oklab, {{sidebar_light_text}} 72%, {{sidebar_light_bg}}); --color-faint: color-mix(in oklab, {{sidebar_light_text}} 45%, {{sidebar_light_bg}}); --color-heading: color-mix(in oklab, {{sidebar_light_text}} 55%, {{sidebar_light_bg.on}}); color-scheme: {{sidebar_light_bg.tone}}; }
html:not(.dark) .op-logo .op-logo-on-dark, html:not(.dark) .op-logo .op-logo-on-light { display: none; }
html:not(.dark) .op-logo .op-logo-on-{{sidebar_light_bg.tone}} { display: inline; }

:where(html.dark) :is(.op-sidebar, .op-panel-sidebar) { background: {{sidebar_dark_bg}}; --color-page: {{sidebar_dark_bg}}; --color-inset: {{sidebar_dark_bg}}; --color-panel: color-mix(in oklab, {{sidebar_dark_text}} 9%, {{sidebar_dark_bg}}); --color-raised: color-mix(in oklab, {{sidebar_dark_text}} 20%, {{sidebar_dark_bg}}); --color-muted: color-mix(in oklab, {{sidebar_dark_text}} 72%, {{sidebar_dark_bg}}); --color-faint: color-mix(in oklab, {{sidebar_dark_text}} 45%, {{sidebar_dark_bg}}); --color-heading: color-mix(in oklab, {{sidebar_dark_text}} 55%, {{sidebar_dark_bg.on}}); color-scheme: {{sidebar_dark_bg.tone}}; }
html.dark .op-logo .op-logo-on-dark, html.dark .op-logo .op-logo-on-light { display: none; }
html.dark .op-logo .op-logo-on-{{sidebar_dark_bg.tone}} { display: inline; }
